class ConflictError extends Error {
  override name = "ConflictError";
}
class ValidationError extends Error {
  override name = "ValidationError";
}

const books = new Map<number, { priceCents: number; stock: number }>([[1, { priceCents: 1299, stock: 3 }]]);

function place(bookId: number, quantity: number): { bookId: number; quantity: number; totalCents: number } {
  const book = books.get(bookId);
  if (book === undefined) throw new ValidationError(`bookId ${bookId} does not exist`);
  if (book.stock < quantity) throw new ConflictError(`Only ${book.stock} left of book ${bookId}`);
  book.stock -= quantity;
  return { bookId, quantity, totalCents: book.priceCents * quantity };
}

for (const [bookId, quantity] of [[1, 2], [1, 5], [99, 1]] as const) {
  try {
    console.log(JSON.stringify(place(bookId, quantity)));
  } catch (error) {
    if (error instanceof Error) console.log(error.name, error.message);
  }
}

